//
// The Synth FX default pack, as the firmware carries it (synthfxPack.inc, generated by
// tools/synthfx/build_pack.py --embed from synthfx-sdk/pack/). Written to /SynthFX/ for each
// file that is missing there (synthfxPlugins.cpp). In flash.

#include "modsBuild.h"

#if MT_HAS_SYNTHFX

#include "synthfxPlugins.h"

namespace mods
{
namespace synthfx
{
namespace plugins
{

namespace
{
#include "synthfxPack.inc"
} // namespace

size_t packCount()
{
    return sizeof(kPack) / sizeof(kPack[0]);
}

const PackFile& packAt(size_t index)
{
    return kPack[index < packCount() ? index : 0];
}

} // namespace plugins
} // namespace synthfx
} // namespace mods

#endif // MT_HAS_SYNTHFX
